using UnityEngine;

/// <summary>
/// Designer-tunable values for the wrench multitool's swing + throw abilities.
/// One asset lives in Configs/Player/. Referenced by the wrench controllers and
/// the aim reticle so all wrench feel is data-driven in one place.
/// </summary>
[CreateAssetMenu(menuName = "Flynn/Wrench Config", fileName = "WrenchConfig")]
public class WrenchConfig : ScriptableObject
{
    [Header("Swing (Left Click)")]
    [Tooltip("Seconds of hold to reach a full-power (heavy) swing.")]
    public float swingChargeTime = 1.2f;
    [Tooltip("Charge fraction (0-1) at/above which a swing counts as heavy.")]
    [Range(0f, 1f)] public float heavySwingThreshold = 0.6f;
    public float lightSwingCooldown = 0.45f;
    public float heavySwingCooldown = 0.8f;

    [Tooltip("Release playback speed for a zero-charge (light) swing.")]
    [Min(0.1f)] public float lightSwingAnimSpeed = 1.0f;
    [Tooltip("Release playback speed for a full-charge (heavy) swing — fast follow-through, the stored power releasing. Release speed lerps light→heavy by charge.")]
    [Min(0.1f)] public float heavySwingAnimSpeed = 2.5f;

    [Header("Harvest Damage")]
    [Tooltip("Damage points applied to a ResourceNode on a light swing.")]
    [Min(1)] public int lightSwingDamage = 1;
    [Tooltip("Damage points applied to a ResourceNode on a heavy swing.")]
    [Min(1)] public int heavySwingDamage = 2;

    [Header("Throw (Right Click)")]
    [Tooltip("Seconds of hold to reach max throw distance.")]
    public float throwChargeTime = 0.8f;
    public float minThrowDistance = 3f;
    public float maxThrowDistance = 9f;
    [Tooltip("Outbound travel speed (units/sec).")]
    public float throwSpeed = 12f;
    [Tooltip("Visual spin speed of the thrown wrench (deg/sec).")]
    public float spinSpeed = 720f;
    [Tooltip("Seconds the wrench hovers at the apex before boomeranging back.")]
    public float returnDelay = 0.4f;
    [Tooltip("Homing speed on the return leg (units/sec).")]
    public float returnSpeed = 14f;
    [Tooltip("Distance to the catch point at which a returning wrench is caught.")]
    public float catchRadius = 0.6f;
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Left-click swing for the wrench multitool. Hold to charge power via
/// <see cref="PowerBuildupManager"/>; release to swing with scaled damage and
/// battery cost. Tap for a light swing. The swing faces the mouse aim point.
/// Routes damage through the ResourceManager observer pattern.
/// Disabled while the wrench is airborne (thrown).
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class WrenchSwingController : MonoBehaviour
{
    private const int WrenchAnimIndex = 4;

    [SerializeField] private WrenchConfig _config;
    [SerializeField] private PowerBuildupSettings _buildupSettings;
    [Tooltip("Optional — used to block swinging while the wrench is mid-throw.")]
    [SerializeField] private WrenchThrowController _throw;

    [Tooltip("Directional swipe arc visual. Fed the player→mouse direction on each swing.")]
    [SerializeField] private WrenchSwingArc _swingArc;

    [Tooltip("Cooldown between swings (seconds).")]
    [SerializeField] private float _cooldownTime = 0.1f;

    [Tooltip("Max distance from player for a melee hit. Beyond this is just a whoosh.")]
    [SerializeField] private float _swingRange = 1.5f;

    [Tooltip("Hold longer than this (seconds) to enter windup. Taps skip straight to swing.")]
    [SerializeField] private float _quickSwingThreshold = 0.12f;

    private PlayerMouseAimer _aimer;
    private PlayerInitializer _playerInit;
    private IPlayerVisual _animDriver;
    private SolarpunkCharacterController _movement;
    private PowerBuildupManager _buildup;
    private float _cooldown;
    private float _windupStartTime;

    public bool IsCharging => _buildup != null && _buildup.IsCharging && _buildup.CurrentType == ActionType.Swing;
    public float ChargeNormalized => _buildup != null ? _buildup.ChargeNormalized : 0f;

    /// <summary>True while the swing animation is still playing (movement blocked).</summary>
    public bool IsSwinging { get; private set; }

    private void Awake()
    {
        _aimer      = GetComponent<PlayerMouseAimer>();
        _animDriver = GetComponent<IPlayerVisual>();
        _playerInit = GetComponent<PlayerInitializer>();
        _movement   = GetComponent<SolarpunkCharacterController>();
    }

    private void Update()
    {
        // Block movement while swinging
        if (IsSwinging)
        {
            if (_movement != null) _movement.CanMove = false;

            // Check if the swing animation has finished
            var driver = _animDriver as FlynnAnimationDriver;
            if (driver != null && !driver.IsAttacking)
                IsSwinging = false;
        }

        if (_cooldown > 0f) _cooldown -= Time.deltaTime;

        bool usable = PlayerInventory.Instance != null
                      && PlayerInventory.Instance.ActiveItemType == ItemType.Wrench
                      && (_throw == null || !_throw.IsAirborne);
        if (!usable)
        {
            if (IsCharging) _buildup.CancelCharge();
            if (_animDriver is FlynnAnimationDriver drv)
                drv.CancelSwingWindup();
            return;
        }

        if (_buildup == null) _buildup = PowerBuildupManager.Instance;

        if (Input.GetMouseButtonDown(0) && _cooldown <= 0f)
        {
            if (_buildup != null) _buildup.BeginCharge(ActionType.Swing);
            _windupStartTime = Time.time;
            // Face the mouse aim point and start the windup animation
            if (_animDriver != null)
            {
                _animDriver.FaceWorldDirection(_aimer.WorldAimPoint - transform.position);
                _animDriver.BeginSwingWindup();
            }
        }
        else if (IsCharging && Input.GetMouseButtonUp(0))
        {
            bool quickSwing = Time.time - _windupStartTime < _quickSwingThreshold;
            DoSwing(quickSwing);
        }
    }

    private void DoSwing(bool quickSwing = false)
    {
        if (_buildup == null) return;

        ChargeResult result = _buildup.ReleaseCharge();

        // Face the swing toward the mouse direction regardless of range
        if (_animDriver != null)
            _animDriver.FaceWorldDirection(_aimer.WorldAimPoint - transform.position);

        int animIndex = _aimer.SwingAnimIndex;
        if (animIndex <= 0) animIndex = WrenchAnimIndex;

        float speed = result.AnimSpeed > 0f ? result.AnimSpeed : 1f;
        if (_animDriver != null)
        {
            if (quickSwing)
            {
                _animDriver.CancelSwingWindup();
                _animDriver.TriggerSwing();
            }
            else
            {
                _animDriver.ReleaseSwing(animIndex, speed);
            }
        }

        IsSwinging = true;
        if (_movement != null) _movement.CanMove = false;

        // Only apply damage if a hittable target (ResourceNode or HittableSurface) is within swing range
        bool inRange = false;
        Vector3 hitPoint = transform.position;

        if (_aimer.MeleeResource != null)
        {
            // ResourceNode within the aimer's melee range — also check our tighter swing range
            float dist = Vector3.Distance(transform.position, _aimer.WorldAimPoint);
            if (dist <= _swingRange)
            {
                inRange = true;
                hitPoint = _aimer.WorldAimPoint;
            }
        }
        else if (_aimer.HoveredGameObject != null)
        {
            // Check for HittableSurface (non-resource props) within swing range
            var surface = _aimer.HoveredGameObject.GetComponentInParent<HittableSurface>();
            float dist = Vector3.Distance(transform.position, _aimer.WorldAimPoint);
            if (surface != null && dist <= _swingRange)
            {
                inRange = true;
                hitPoint = _aimer.WorldAimPoint;
            }
        }
        // Ground / distant objects = whoosh (no damage)

        if (_swingArc != null)
            _swingArc.Play(hitPoint);

        _cooldown = _cooldownTime;

        if (inRange)
        {
            int damage = result.Damage > 0 ? result.Damage : 1;
            GameObject target = _aimer.HoveredGameObject;
            if (_playerInit != null && damage > 0)
                _playerInit.EmitHit(hitPoint, target, damage);
        }

        ToolType tool = PlayerInventory.Instance != null
            ? ToolHitContext.FromItemType(PlayerInventory.Instance.ActiveItemType)
            : ToolType.Wrench;
        PublishEvent(new ToolSwingStarted(tool, hitPoint));
    }

    private static void PublishEvent<T>(T evt) where T : struct
    {
        if (GameEventBus.Instance != null) GameEventBus.Instance.Publish(evt);
    }
}

